135→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
136→	cfg := &runConfig{Model: defaultDroidModel}
137→	for _, o := range opts {
138→		o(cfg)
139→	}
140→
141→	model := cfg.Model
142→	if model == "" {
143→		model = defaultDroidModel
144→	}
145→
146→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
147→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
148→
149→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
150→	cmd.Dir = dir
151→	cmd.Stdin = nil
152→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
153→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
154→	cmd.Cancel = func() error {
155→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
156→	}
157→	cmd.WaitDelay = 5 * time.Second
158→
159→	var stdout, stderr strings.Builder
160→	cmd.Stdout = &stdout
161→	cmd.Stderr = &stderr
162→
163→	err := cmd.Run()
164→	exitCode := 0
165→	if err != nil {
166→		exitErr := &exec.ExitError{}
167→		if errors.As(err, &exitErr) {
168→			exitCode = exitErr.ExitCode()
169→		} else {
170→			exitCode = -1
171→		}
172→	}
173→
174→	return Output{
175→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
176→		Stdout:   stdout.String(),
177→		Stderr:   stderr.String(),
178→		ExitCode: exitCode,
179→	}, err
180→}
