182→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
183→	const maxAttempts = 3
184→
185→	var s *TmuxSession
186→	var lastErr error
187→	for attempt := range maxAttempts {
188→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
189→		var err error
190→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary(), "--model", defaultDroidModel, "--skip-permissions-unsafe")
191→		if err != nil {
192→			return nil, err
193→		}
194→
195→		// Wait for the interactive prompt indicator.
196→		if _, err := s.WaitFor(d.PromptPattern(), 30*time.Second); err != nil {
197→			_ = s.Close()
198→			if attempt < maxAttempts-1 {
199→				lastErr = err
200→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed: %s\n", attempt+1, maxAttempts, err)
201→				continue
202→			}
203→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", maxAttempts, err)
204→		}
205→		s.stableAtSend = ""
206→		return s, nil
207→	}
208→	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", maxAttempts, lastErr)
209→}
